<?php require __DIR__.'/app.php';render_header('Giỏ hàng');?><section class="page-heading"><span class="eyebrow">ĐƠN HÀNG CỦA BẠN</span><h1>Giỏ hàng</h1></section><?php if(!$items):?><div class="empty-state">Giỏ hàng đang trống. <a href="index.php?page=sanpham">Tiếp tục mua sắm</a></div><?php else:?><div class="cart-layout"><form method="post" action="index.php?page=capnhat_don"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php foreach($items as $item):?><div class="cart-row"><img src="<?=e(image_url($item))?>" alt=""><div><b><?=e($item['name'])?></b><small><?=money($item['sale_price'])?></small></div><input type="number" min="1" max="99" name="quantity[<?=(int)$item['id']?>]" value="<?=(int)$item['quantity']?>"><strong><?=money($item['line_total'])?></strong><button class="button button-plain" name="remove_id" value="<?=(int)$item['id']?>">Xóa</button></div><?php endforeach;?><button class="button button-light">Cập nhật giỏ hàng</button></form><aside class="summary"><h2>Tóm tắt đơn hàng</h2><p>Tạm tính <strong><?=money($subtotal)?></strong></p><p>Phí vận chuyển <strong><?=$shippingFee>0?money($shippingFee):'Miễn phí'?></strong></p><hr><p>Tổng thanh toán <strong><?=money($total)?></strong></p><small>Phí 100.000₫; miễn phí khi tiền hàng từ 5.000.000₫.</small><a class="button button-orange full" href="index.php?page=thanhtoan">Tiến hành đặt hàng</a></aside></div><?php endif;?><?php render_footer();?>